package com.humanresource.onboarding;

import com.fasterxml.jackson.databind.*;
import com.hris.common.utilities.UseUtils;
import com.humanresource.entitymodels.*;
import com.humanresource.integration.primehr.AppointmentHandoffReceiptRecord;
import com.humanresource.onboarding.OnboardingDtos.*;
import com.humanresource.repositories.*;
import microsoft.sql.DateTimeOffset;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

@Service
public class OnboardingService implements AppointmentHandoffAcceptedListener {
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final EmployeeRepository employees;private final EmployeeAppointmentRepository appointments;private final AdministrativeAppointmentSourceClient sources;private final PasswordEncoder passwords;private final Duration activationTtl;
    public OnboardingService(JdbcTemplate j,ObjectMapper o,EmployeeRepository e,EmployeeAppointmentRepository a,AdministrativeAppointmentSourceClient s,PasswordEncoder p,@Value("${hrm.employee-activation.ttl-hours:72}")long ttl){jdbc=j;json=o;employees=e;appointments=a;sources=s;passwords=p;activationTtl=Duration.ofHours(Math.max(1,ttl));}

    @Override @Transactional public void accepted(AppointmentHandoffReceiptRecord receipt){if(count("SELECT COUNT(*) FROM hrm_onboarding_case WHERE agency_id=? AND handoff_id=?",receipt.agencyId(),receipt.handoffId())>0)return;Map<String,Object> template=one("SELECT id,template_code,definition_version FROM hrm_onboarding_template WHERE agency_id=? AND status='PUBLISHED' AND (effective_from IS NULL OR effective_from<=?) AND (effective_to IS NULL OR effective_to>=?) ORDER BY definition_version DESC",receipt.agencyId(),LocalDate.now(),LocalDate.now());if(template==null)throw conflict("No effective published onboarding template is configured");String templateId=text(template,"id"),caseId=UUID.randomUUID().toString();List<Map<String,Object>> items=jdbc.queryForList("SELECT id,item_code,label,instructions,required_item,evidence_required,evidence_classification,retention_tag,responsible_role,display_order,completion_rule FROM hrm_onboarding_template_item WHERE template_id=? ORDER BY display_order,item_code",templateId);if(items.isEmpty())throw conflict("The effective onboarding template has no items");String snapshot=write(Map.of("templateId",templateId,"templateCode",text(template,"template_code"),"definitionVersion",number(template,"definition_version"),"items",items));Instant now=Instant.now();jdbc.update("INSERT INTO hrm_onboarding_case(id,agency_id,handoff_receipt_id,handoff_id,template_id,template_version,template_snapshot,status,source_fingerprint,record_version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'RECEIVED',?,0,?,?)",caseId,receipt.agencyId(),receipt.id(),receipt.handoffId(),templateId,number(template,"definition_version"),snapshot,receipt.sourceFingerprint(),ts(now),ts(now));for(Map<String,Object> item:items)jdbc.update("INSERT INTO hrm_onboarding_item(id,onboarding_case_id,template_item_id,item_code,label,required_item,evidence_required,evidence_classification,retention_tag,responsible_role,display_order,completion_rule,status,record_version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'PENDING',0)",UUID.randomUUID().toString(),caseId,text(item,"id"),text(item,"item_code"),text(item,"label"),bool(item,"required_item"),bool(item,"evidence_required"),item.get("evidence_classification"),item.get("retention_tag"),text(item,"responsible_role"),number(item,"display_order"),text(item,"completion_rule"));audit(caseId,receipt.agencyId(),"RECEIVE_HANDOFF",receipt.sourceActor(),receipt.sourceFingerprint());}

    @Transactional public TemplateResponse createTemplate(String agency,String actor,TemplateCommand command){if(command.effectiveFrom()!=null&&command.effectiveTo()!=null&&command.effectiveTo().isBefore(command.effectiveFrom()))throw bad("Template effectivity is invalid");int version=count("SELECT COALESCE(MAX(definition_version),0)+1 FROM hrm_onboarding_template WHERE agency_id=? AND template_code=?",agency,command.code());String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO hrm_onboarding_template(id,agency_id,template_code,definition_version,status,effective_from,effective_to,created_by,created_at) VALUES(?,?,?,?,'DRAFT',?,?,?,?)",id,agency,command.code(),version,command.effectiveFrom(),command.effectiveTo(),actor,ts(Instant.now()));for(TemplateItem i:command.items())jdbc.update("INSERT INTO hrm_onboarding_template_item(id,template_id,item_code,label,instructions,required_item,evidence_required,evidence_classification,retention_tag,responsible_role,display_order,completion_rule) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID().toString(),id,i.code(),i.label(),i.instructions(),i.required(),i.evidenceRequired(),i.evidenceClassification(),i.retentionTag(),i.responsibleRole(),i.displayOrder(),i.completionRule());return new TemplateResponse(id,command.code(),version,"DRAFT",command.effectiveFrom(),command.effectiveTo(),0);}
    @Transactional public TemplateResponse publishTemplate(String agency,String id,String actor){Map<String,Object> t=requireTemplate(agency,id);if(!"DRAFT".equals(text(t,"status")))throw conflict("Only a draft template may be published");Instant now=Instant.now();jdbc.update("UPDATE hrm_onboarding_template SET status='SUPERSEDED',superseded_at=? WHERE agency_id=? AND template_code=? AND status='PUBLISHED'",ts(now),agency,text(t,"template_code"));jdbc.update("UPDATE hrm_onboarding_template SET status='PUBLISHED',published_at=? WHERE id=? AND status='DRAFT'",ts(now),id);return new TemplateResponse(id,text(t,"template_code"),number(t,"definition_version"),"PUBLISHED",date(t,"effective_from"),date(t,"effective_to"),0);}
    @Transactional(readOnly=true) public List<IntakeResponse> list(String agency){return jdbc.queryForList("SELECT c.id FROM hrm_onboarding_case c WHERE c.agency_id=? ORDER BY c.created_at DESC",agency).stream().map(x->get(agency,text(x,"id"))).toList();}
    @Transactional(readOnly=true) public IntakeResponse get(String agency,String id){Map<String,Object> c=requireCase(agency,id);Map<String,Object> r=one("SELECT selection_id,application_id,applicant_id FROM rsp_appointment_handoff_receipt WHERE id=?",text(c,"handoff_receipt_id"));List<ItemResponse> items=jdbc.queryForList("SELECT id,item_code,label,required_item,evidence_required,status,evidence_reference,completed_by,verified_by,record_version FROM hrm_onboarding_item WHERE onboarding_case_id=? ORDER BY display_order,item_code",id).stream().map(this::item).toList();return new IntakeResponse(id,text(c,"handoff_id"),text(r,"selection_id"),text(r,"application_id"),text(r,"applicant_id"),text(c,"status"),(String)c.get("identity_decision"),longOrNull(c,"employee_id"),(String)c.get("proposed_employee_no"),longOrNull(c,"appointment_id"),longValue(c,"record_version"),items);}
    @Transactional public IntakeResponse begin(String agency,String id,long version,String actor){transition(agency,id,version,Set.of("RECEIVED","RETURNED"),"IN_REVIEW",null,null);audit(id,agency,"BEGIN_REVIEW",actor,null);return get(agency,id);}
    @Transactional public IntakeResponse returnCase(String agency,String id,ReasonCommand command,String actor){if(command.reason().isBlank())throw bad("Return reason is required");transition(agency,id,command.recordVersion(),Set.of("IN_REVIEW"),"RETURNED","return_reason",command.reason());audit(id,agency,"RETURN",actor,null);return get(agency,id);}
    @Transactional public IntakeResponse identity(String agency,String id,IdentityCommand command,String actor){Map<String,Object> c=requireCaseVersion(agency,id,command.recordVersion());if(!Set.of("IN_REVIEW","RETURNED").contains(text(c,"status")))throw conflict("Identity may only be resolved during review");String decision=command.decision();Long employeeId=null;String no=null,bio=null,role=null;if("LINK_EXISTING_EMPLOYEE".equals(decision)){if(command.employeeId()==null)throw bad("Exact employee ID is required");Employee e=employees.findById(command.employeeId()).orElseThrow(()->bad("Employee was not found"));if(command.employeeNo()==null||!e.getEmployeeNo().equals(command.employeeNo()))throw bad("Employee ID and number do not match");employeeId=e.getEmployeeId();no=e.getEmployeeNo();}else if("CREATE_NEW_EMPLOYEE".equals(decision)){no=required(command.employeeNo(),"Employee number");bio=required(command.biometricNo(),"Biometric number");role=required(command.role(),"Employee role");if("1".equals(role.trim().replaceFirst("(?i)^ROLE_","")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator role cannot be assigned by appointment intake");if(employees.findByEmployeeNo(no).isPresent()||employees.existsByBiometricNo(bio))throw conflict("Employee or biometric number already exists");}else throw bad("Unsupported identity decision");int changed=jdbc.update("UPDATE hrm_onboarding_case SET identity_decision=?,employee_id=?,proposed_employee_no=?,proposed_biometric_no=?,proposed_role=?,record_version=record_version+1,updated_at=? WHERE id=? AND agency_id=? AND record_version=?",decision,employeeId,no,bio,role,ts(Instant.now()),id,agency,command.recordVersion());if(changed!=1)throw conflict("Onboarding case changed");audit(id,agency,"IDENTITY_RESOLUTION",actor,decision);return get(agency,id);}
    @Transactional public IntakeResponse checklist(String agency,String id,String itemId,ChecklistCommand command,String actor){requireCaseVersion(agency,id,command.recordVersion());Map<String,Object> item=one("SELECT * FROM hrm_onboarding_item WHERE id=? AND onboarding_case_id=?",itemId,id);if(item==null)throw notFound("Onboarding item was not found");String status=command.status();if("SUBMITTED".equals(status)){if(bool(item,"evidence_required")&&(blank(command.evidenceReference())||blank(command.evidenceFingerprint())))throw bad("Evidence reference and fingerprint are required");jdbc.update("UPDATE hrm_onboarding_item SET status='SUBMITTED',evidence_reference=?,evidence_fingerprint=?,completed_by=?,completed_at=?,verified_by=NULL,verified_at=NULL,record_version=record_version+1 WHERE id=?",command.evidenceReference(),command.evidenceFingerprint(),actor,ts(Instant.now()),itemId);}else if("VERIFIED".equals(status)){if(!"SUBMITTED".equals(text(item,"status")))throw conflict("Only submitted evidence may be verified");if(actor.equals(text(item,"completed_by")))throw conflict("Independent verification requires a different user");jdbc.update("UPDATE hrm_onboarding_item SET status='VERIFIED',verified_by=?,verified_at=?,record_version=record_version+1 WHERE id=?",actor,ts(Instant.now()),itemId);}else if("REJECTED".equals(status)){jdbc.update("UPDATE hrm_onboarding_item SET status='REJECTED',verified_by=?,verified_at=?,record_version=record_version+1 WHERE id=?",actor,ts(Instant.now()),itemId);}else throw bad("Unsupported checklist status");touch(id,agency,command.recordVersion());audit(id,agency,"CHECKLIST_"+status,actor,itemId);return get(agency,id);}
    @Transactional public IntakeResponse approve(String agency,String id,long version,String actor){Map<String,Object> c=requireCaseVersion(agency,id,version);if(!"IN_REVIEW".equals(text(c,"status"))||c.get("identity_decision")==null)throw conflict("Reviewed identity resolution is required");if(count("SELECT COUNT(*) FROM hrm_onboarding_item WHERE onboarding_case_id=? AND required_item=? AND status<>'VERIFIED'",id,true)>0)throw conflict("All required onboarding items require independent verification");transition(agency,id,version,Set.of("IN_REVIEW"),"READY_FOR_APPOINTMENT",null,null);audit(id,agency,"APPROVE_FOR_APPOINTMENT",actor,null);return get(agency,id);}

    @Transactional public AppointmentResult createAppointment(String agency,String id,AppointmentCommand command,String actor,String bearer){Map<String,Object> existing=one("SELECT employee_id,employee_appointment_id FROM hrm_appointment_provenance WHERE agency_id=? AND onboarding_case_id=?",agency,id);if(existing!=null){IntakeResponse c=get(agency,id);return new AppointmentResult(id,longOrNull(existing,"employee_id"),longOrNull(existing,"employee_appointment_id"),c.status(),null,null,c.recordVersion());}Map<String,Object> c=requireCaseVersion(agency,id,command.recordVersion());if(!"READY_FOR_APPOINTMENT".equals(text(c,"status")))throw conflict("Onboarding case is not ready for appointment");if(command.appointmentIssuedDate().isAfter(command.assumptionToDutyDate()))throw bad("Appointment issued date cannot be after assumption to duty");lockCase(id,agency,command.recordVersion());Map<String,Object> receipt=one("SELECT selection_id,application_id,payload_snapshot,source_fingerprint FROM rsp_appointment_handoff_receipt WHERE id=?",text(c,"handoff_receipt_id"));JsonNode payload=read(text(receipt,"payload_snapshot"));JsonNode position=payload.path("position"),applicant=payload.path("applicant");long plantilla=position.path("plantillaId").asLong(),job=position.path("jobPositionId").asLong(),unit=position.path("businessUnitId").asLong();var source=sources.resolve(bearer,plantilla,unit,command.natureOfAppointmentId(),command.assumptionToDutyDate());if(!Objects.equals(source.plantillaId(),plantilla)||!Objects.equals(source.jobPositionId(),job)||!Objects.equals(source.businessUnitId(),unit))throw conflict("Administrative appointment source changed");if(!text(position,"plantillaName").equals(source.plantillaName())||!text(position,"jobPositionName").equals(source.jobPositionName()))throw conflict("Administrative position identity changed");List<EmployeeAppointment> occupied=appointments.findActiveByPlantillaForUpdate(Math.toIntExact(plantilla));Long linked=longOrNull(c,"employee_id");if(!occupied.isEmpty()&&(linked==null||!occupied.get(0).getEmployeeId().equals(linked)))throw conflict("Plantilla is already occupied");boolean created="CREATE_NEW_EMPLOYEE".equals(text(c,"identity_decision"));Employee employee;if(created){String email=text(applicant,"email");if(employees.findByEmployeeNo(text(c,"proposed_employee_no")).isPresent()||employees.existsByBiometricNo(text(c,"proposed_biometric_no"))||(!blank(email)&&employees.existsByEmailIgnoreCase(email)))throw conflict("Employee identity is no longer unique");employee=new Employee(text(c,"proposed_employee_no"),passwords.encode(UUID.randomUUID().toString()),text(c,"proposed_biometric_no"),text(c,"proposed_role"),text(applicant,"givenName"),text(applicant,"familyName"),nullableText(applicant,"suffix"),email,source.jobPositionName(),"",UseUtils.getLocalDateTimeNow(),UseUtils.getLocalDateTimeNow());employee=employees.saveAndFlush(employee);}else{employee=employees.findByIdForUpdate(linked).orElseThrow(()->conflict("Linked employee no longer exists"));}List<EmployeeAppointment> active=appointments.findActiveByEmployeeForUpdate(employee.getEmployeeId());for(EmployeeAppointment prior:active){if(!command.assumptionToDutyDate().isAfter(prior.getAssumptionToDutyDate()))throw conflict("New appointment must be later than the active appointment");}EmployeeAppointment appointment=new EmployeeAppointment(employee.getEmployeeId(),command.appointmentIssuedDate(),command.assumptionToDutyDate(),Math.toIntExact(command.natureOfAppointmentId()),Math.toIntExact(plantilla),Math.toIntExact(job),Math.toIntExact(source.salaryGrade()),Math.toIntExact(source.salaryStep()),source.annualSalary(),source.monthlySalary(),source.dailySalary(),command.details(),true);active.forEach(a->a.setActiveAppointment(false));appointments.saveAll(active);appointment=appointments.saveAndFlush(appointment);Instant now=Instant.now();jdbc.update("INSERT INTO hrm_appointment_provenance(id,agency_id,onboarding_case_id,handoff_id,selection_id,application_id,employee_id,employee_appointment_id,plantilla_id,source_fingerprint,administrative_fingerprint,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID().toString(),agency,id,text(c,"handoff_id"),text(receipt,"selection_id"),text(receipt,"application_id"),employee.getEmployeeId(),appointment.getEmployeeAppointmentId(),plantilla,text(receipt,"source_fingerprint"),source.sourceFingerprint(),actor,ts(now));String plain=null;Instant expiry=null;if(created){plain=randomToken();expiry=now.plus(activationTtl);jdbc.update("INSERT INTO employee_activation_invitation(id,employee_id,onboarding_case_id,token_hash,expires_at,created_at) VALUES(?,?,?,?,?,?)",UUID.randomUUID().toString(),employee.getEmployeeId(),id,sha(plain),ts(expiry),ts(now));}jdbc.update("UPDATE hrm_onboarding_case SET status='APPOINTMENT_CREATED',employee_id=?,appointment_id=?,record_version=record_version+1,updated_at=? WHERE id=?",employee.getEmployeeId(),appointment.getEmployeeAppointmentId(),ts(now),id);jdbc.update("UPDATE rsp_appointment_handoff_receipt SET state='APPOINTMENT_CREATED',record_version=record_version+1,updated_at=? WHERE id=?",ts(now),text(c,"handoff_receipt_id"));audit(id,agency,"CREATE_APPOINTMENT",actor,source.sourceFingerprint());return new AppointmentResult(id,employee.getEmployeeId(),appointment.getEmployeeAppointmentId(),"APPOINTMENT_CREATED",plain,expiry,command.recordVersion()+1);}
    @Transactional public IntakeResponse complete(String agency,String id,long version,String actor){Map<String,Object> c=requireCaseVersion(agency,id,version);if(!"APPOINTMENT_CREATED".equals(text(c,"status")))throw conflict("Appointment must be created first");if(count("SELECT COUNT(*) FROM hrm_onboarding_item WHERE onboarding_case_id=? AND required_item=? AND status<>'VERIFIED'",id,true)>0)throw conflict("Required onboarding remains incomplete");transition(agency,id,version,Set.of("APPOINTMENT_CREATED"),"COMPLETED",null,null);jdbc.update("UPDATE rsp_appointment_handoff_receipt SET state='COMPLETED',record_version=record_version+1,updated_at=? WHERE id=?",ts(Instant.now()),text(c,"handoff_receipt_id"));audit(id,agency,"COMPLETE_ONBOARDING",actor,null);return get(agency,id);}
    @Transactional public void activate(ActivationCommand command){String hash=sha(command.token());Map<String,Object> invitation=one("SELECT employee_id,expires_at,consumed_at,revoked_at FROM employee_activation_invitation WHERE token_hash=?",hash);if(invitation==null||invitation.get("consumed_at")!=null||invitation.get("revoked_at")!=null||instant(invitation,"expires_at").isBefore(Instant.now()))throw bad("Activation invitation is invalid or expired");Employee employee=employees.findByIdForUpdate(longOrNull(invitation,"employee_id")).orElseThrow(()->bad("Employee was not found"));employee.setEmployeePassword(passwords.encode(command.password()));employees.saveAndFlush(employee);int changed=jdbc.update("UPDATE employee_activation_invitation SET consumed_at=? WHERE token_hash=? AND consumed_at IS NULL AND revoked_at IS NULL",ts(Instant.now()),hash);if(changed!=1)throw conflict("Activation invitation was already consumed");}

    private void transition(String agency,String id,long version,Set<String> from,String to,String reasonColumn,String reason){Map<String,Object> c=requireCaseVersion(agency,id,version);if(!from.contains(text(c,"status")))throw conflict("Invalid onboarding status transition");String sql="UPDATE hrm_onboarding_case SET status=?"+(reasonColumn==null?"":","+reasonColumn+"=?")+",record_version=record_version+1,updated_at=? WHERE id=? AND agency_id=? AND record_version=?";int n=reasonColumn==null?jdbc.update(sql,to,ts(Instant.now()),id,agency,version):jdbc.update(sql,to,reason,ts(Instant.now()),id,agency,version);if(n!=1)throw conflict("Onboarding case changed");}
    private void touch(String id,String agency,long version){if(jdbc.update("UPDATE hrm_onboarding_case SET record_version=record_version+1,updated_at=? WHERE id=? AND agency_id=? AND record_version=?",ts(Instant.now()),id,agency,version)!=1)throw conflict("Onboarding case changed");}
    private void lockCase(String id,String agency,long version){if(jdbc.update("UPDATE hrm_onboarding_case SET updated_at=updated_at WHERE id=? AND agency_id=? AND record_version=?",id,agency,version)!=1)throw conflict("Onboarding case changed");}
    private Map<String,Object> requireCase(String agency,String id){Map<String,Object> value=one("SELECT * FROM hrm_onboarding_case WHERE id=? AND agency_id=?",id,agency);if(value==null)throw notFound("Onboarding intake was not found");return value;}
    private Map<String,Object> requireCaseVersion(String agency,String id,long v){Map<String,Object> c=requireCase(agency,id);if(longValue(c,"record_version")!=v)throw conflict("Onboarding case record version changed");return c;}
    private Map<String,Object> requireTemplate(String agency,String id){Map<String,Object> v=one("SELECT * FROM hrm_onboarding_template WHERE id=? AND agency_id=?",id,agency);if(v==null)throw notFound("Onboarding template was not found");return v;}
    private void audit(String caseId,String agency,String action,String actor,String summary){jdbc.update("INSERT INTO hrm_onboarding_audit_event(id,agency_id,onboarding_case_id,action_code,actor,safe_summary,occurred_at) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID().toString(),agency,caseId,action,actor,summary,ts(Instant.now()));}
    private ItemResponse item(Map<String,Object> x){return new ItemResponse(text(x,"id"),text(x,"item_code"),text(x,"label"),bool(x,"required_item"),bool(x,"evidence_required"),text(x,"status"),(String)x.get("evidence_reference"),(String)x.get("completed_by"),(String)x.get("verified_by"),longValue(x,"record_version"));}
    private Map<String,Object> one(String sql,Object...args){List<Map<String,Object>> rows=jdbc.queryForList(sql,args);return rows.isEmpty()?null:rows.get(0);}private int count(String sql,Object...args){Number n=jdbc.queryForObject(sql,Number.class,args);return n==null?0:n.intValue();}
    private static String text(Map<String,Object> m,String k){Object v=m.get(k);if(v==null)throw new IllegalStateException(k+" is missing");return v.toString();}private static String nullableText(JsonNode n,String k){return n.path(k).isNull()?null:n.path(k).asText(null);}private static String text(JsonNode n,String k){String v=n.path(k).asText(null);if(blank(v))throw bad(k+" is missing");return v;}private static int number(Map<String,Object>m,String k){return ((Number)m.get(k)).intValue();}private static long longValue(Map<String,Object>m,String k){return ((Number)m.get(k)).longValue();}private static Long longOrNull(Map<String,Object>m,String k){Object v=m.get(k);return v==null?null:((Number)v).longValue();}private static boolean bool(Map<String,Object>m,String k){Object v=m.get(k);return v instanceof Boolean b?b:((Number)v).intValue()!=0;}private static LocalDate date(Map<String,Object>m,String k){Object v=m.get(k);return v==null?null:v instanceof java.sql.Date d?d.toLocalDate():LocalDate.parse(v.toString());}private static Instant instant(Map<String,Object>m,String k){Object v=m.get(k);if(v instanceof Timestamp t)return t.toInstant();if(v instanceof DateTimeOffset d)return d.getOffsetDateTime().toInstant();return ((java.time.OffsetDateTime)v).toInstant();}
    private String write(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}private JsonNode read(String v){try{return json.readTree(v);}catch(Exception e){throw new IllegalStateException(e);}}private static Timestamp ts(Instant i){return Timestamp.from(i);}private static String required(String v,String label){if(blank(v))throw bad(label+" is required");return v.trim();}private static boolean blank(String v){return v==null||v.isBlank();}private static String randomToken(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private static String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private static ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
